INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'moral', 'adj./n.', '/ˈmɒrəl/', '道德的;道义上的;品行;道德;寓意', 'Telling the truth is the right moral choice.', '讲真话是正确的道德选择。', 'Morals and Virtues', 1, 0, 'senior', 'wordlist', 'required3', 'U2', 'a moral choice', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'virtue', 'n.', '/ˈvɜːtʃuː/', '高尚的道德;美德;优秀品质', 'Honesty is a virtue admired in every culture.', '诚实是一种在每种文化中都受人敬重的美德。', 'Morals and Virtues', 2, 0, 'senior', 'wordlist', 'required3', 'U2', 'a great virtue', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'dilemma', 'n.', '/dɪˈlemə/', '进退两难的境地;困境', 'She faced a moral dilemma during the exam.', '考试中她面临着一个道德困境。', 'Morals and Virtues', 3, 0, 'senior', 'wordlist', 'required3', 'U2', 'a moral dilemma', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'principle', 'n.', '/ˈprɪnsəpl/', '道德原则;法则;原则', 'Helping others was the principle that guided her whole life.', '助人是指引她一生的原则。', 'Morals and Virtues', 4, 0, 'senior', 'wordlist', 'required3', 'U2', 'a guiding principle', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'precious', 'adj.', '/ˈpreʃəs/', '珍稀的;宝贵的', 'To a person, nothing is more precious than their life.', '对一个人来说,没有什么比生命更宝贵。', 'Morals and Virtues', 5, 0, 'senior', 'wordlist', 'required3', 'U2', 'precious life', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'entrust', 'vt.', '/ɪnˈtrʌst/', '委托;交付', 'If they entrust me with their life, how could I refuse?', '如果他们把生命托付给我,我怎能拒绝?', 'Morals and Virtues', 6, 0, 'senior', 'wordlist', 'required3', 'U2', 'entrust sb with sth', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'reject', 'vt.', '/rɪˈdʒekt/', '拒绝接受;不录用', 'Dr Lin rejected the offer to stay abroad and returned home.', '林大夫拒绝了留在国外的邀请,选择回国。', 'Morals and Virtues', 7, 0, 'senior', 'wordlist', 'required3', 'U2', 'reject an offer', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'rejection', 'n.', '/rɪˈdʒekʃn/', '拒绝;否决;不被接受', 'Hurt by the rejection, she quietly walked away.', '被拒绝刺痛后,她默默地走开了。', 'Morals and Virtues', 8, 0, 'senior', 'wordlist', 'required3', 'U2', 'hurt by the rejection', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'complain', 'vi./vt.', '/kəmˈpleɪn/', '抱怨;发牢骚', 'Her brother complained about the high tuition fees.', '她哥哥抱怨学费太高。', 'Morals and Virtues', 9, 0, 'senior', 'wordlist', 'required3', 'U2', 'complain about', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'complaint', 'n.', '/kəmˈpleɪnt/', '抱怨;投诉;怨言', 'The king grew tired of people who only made complaints.', '国王厌倦了那些只会抱怨的人。', 'Morals and Virtues', 10, 0, 'senior', 'wordlist', 'required3', 'U2', 'make a complaint', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'majority', 'n.', '/məˈdʒɒrəti/', '大部分;大多数', 'Unlike the majority of girls, she chose to study medicine.', '与大多数女孩不同,她选择了学医。', 'Morals and Virtues', 11, 0, 'senior', 'wordlist', 'required3', 'U2', 'the majority of', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'tuition', 'n.', '/tjuˈɪʃn/', '(尤指对小组的)教学;讲课;学费', 'The high tuition fees worried her family.', '高昂的学费让她家人发愁。', 'Morals and Virtues', 12, 0, 'senior', 'wordlist', 'required3', 'U2', 'tuition fees', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'respond', 'vi./vt.', '/rɪˈspɒnd/', '做出反应;回应;回答;回复', 'She did not know how to respond to the question.', '她不知道该如何回应这个问题。', 'Morals and Virtues', 13, 0, 'senior', 'wordlist', 'required3', 'U2', 'respond to', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'response', 'n.', '/rɪˈspɒns/', '反应;回答;回复', 'In response to her kindness, the village changed.', '为回应她的善意,村子发生了改变。', 'Morals and Virtues', 14, 0, 'senior', 'wordlist', 'required3', 'U2', 'in response to', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'elect', 'vt.', '/ɪˈlekt/', '选举;推选', 'In 1954 she was elected to the National People''s Congress.', '1954 年她当选为全国人民代表大会代表。', 'Morals and Virtues', 15, 0, 'senior', 'wordlist', 'required3', 'U2', 'be elected to', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'election', 'n.', '/ɪˈlekʃn/', '选举;推选;当选', 'The student union held an election to choose a new leader.', '学生会举行了选举来推选新的负责人。', 'Morals and Virtues', 16, 0, 'senior', 'wordlist', 'required3', 'U2', 'win an election', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'publish', 'vt.', '/ˈpʌblɪʃ/', '发表(作品);出版', 'She was busy publishing medical research on women and children.', '她忙于发表关于妇女儿童的医学研究。', 'Morals and Virtues', 17, 0, 'senior', 'wordlist', 'required3', 'U2', 'publish research', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'retire', 'vi./vt.', '/rɪˈtaɪə(r)/', '退休;退职;退出', 'Dr Lin did not retire until the day she died.', '林大夫直到去世那天才停下工作。', 'Morals and Virtues', 18, 0, 'senior', 'wordlist', 'required3', 'U2', 'retire from work', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'saving', 'n.', '/ˈseɪvɪŋ/', '节省;节约;[pl.] 储蓄金;存款', 'She left her savings to a kindergarten and a fund for new doctors.', '她把积蓄留给了一所幼儿园和一个扶持新医生的基金。', 'Morals and Virtues', 19, 0, 'senior', 'wordlist', 'required3', 'U2', 'leave one''s savings', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'harm', 'n./vt.', '/hɑːm/', '伤害;损害', 'She felt a duty to keep her neighbours from harm.', '她觉得有责任使邻居免受伤害。', 'Morals and Virtues', 20, 0, 'senior', 'wordlist', 'required3', 'U2', 'keep sb from harm', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'despair', 'n./vi.', '/dɪˈspeə(r)/', '绝望;感到无望', 'The king was in despair as nobody moved the stone.', '看到没人去搬石头,国王感到绝望。', 'Morals and Virtues', 21, 0, 'senior', 'wordlist', 'required3', 'U2', 'in despair', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'disguise', 'vt./n.', '/dɪsˈɡaɪz/', '装扮;假扮;掩盖;伪装', 'The king disguised himself and went to a local village.', '国王装扮了一番,去了当地的村子。', 'Morals and Virtues', 22, 0, 'senior', 'wordlist', 'required3', 'U2', 'in disguise', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'complain about', 'phr.', '/kəmˈpleɪn əˈbaʊt/', '抱怨;对……发牢骚', 'Many villagers complained about the stone but did nothing.', '许多村民抱怨那块石头,却什么也不做。', 'Morals and Virtues', 23, 0, 'senior', 'wordlist', 'required3', 'U2', 'complain about the stone', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'spill', 'vt./vi.', '/spɪl/', '(使)洒出;(使)溢出', 'The milkman crashed into the stone, spilling the milk.', '送奶人撞上石头,把牛奶洒了一地。', 'Morals and Virtues', 24, 0, 'senior', 'wordlist', 'required3', 'U2', 'spill the milk', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'trip over', 'phr.', '/trɪp ˈəʊvə(r)/', '被……绊倒', 'One woman tripped over the stone and dropped her water pot.', '一位妇女被石头绊倒,摔碎了水罐。', 'Morals and Virtues', 25, 0, 'senior', 'wordlist', 'required3', 'U2', 'trip over a stone', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'limp', 'vi.', '/lɪmp/', '跛行;一瘸一拐地走', 'She picked herself up and limped away in tears.', '她爬起来,含着泪一瘸一拐地走开了。', 'Morals and Virtues', 26, 0, 'senior', 'wordlist', 'required3', 'U2', 'limp away', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'in tears', 'phr.', '/ɪn tɪəz/', '流着泪;含着泪', 'The woman walked away in tears after the accident.', '出事后,那位妇女含着泪走开了。', 'Morals and Virtues', 27, 0, 'senior', 'wordlist', 'required3', 'U2', 'be in tears', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'might', 'n.', '/maɪt/', '力量;威力', 'The girl pushed the stone with all her might.', '女孩用尽全力推那块石头。', 'Morals and Virtues', 28, 0, 'senior', 'wordlist', 'required3', 'U2', 'with all one''s might', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'tend', 'vt./vi.', '/tend/', '照顾;照料;倾向;趋于', 'She was more interested in tending patients than in titles.', '比起头衔,她更愿意照料病人。', 'Morals and Virtues', 29, 0, 'senior', 'wordlist', 'required3', 'U2', 'tend patients', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'tend to do sth', 'phr.', '/tend tə duː/', '易于做某事;往往会发生', 'Passive children tend to be ignored by their classmates.', '顺从的孩子往往会被同学忽视。', 'Morals and Virtues', 30, 0, 'senior', 'wordlist', 'required3', 'U2', 'tend to do', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'passive', 'adj.', '/ˈpæsɪv/', '被动的;顺从的', 'Shy, passive children may need more encouragement.', '害羞、顺从的孩子可能需要更多鼓励。', 'Morals and Virtues', 31, 0, 'senior', 'wordlist', 'required3', 'U2', 'passive children', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'energetic', 'adj.', '/ˌenəˈdʒetɪk/', '精力充沛的;充满活力的', 'Energetic young people tend to show interest in their work.', '精力充沛的年轻人往往对工作充满兴趣。', 'Morals and Virtues', 32, 0, 'senior', 'wordlist', 'required3', 'U2', 'energetic young people', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'flexible', 'adj.', '/ˈfleksəbl/', '灵活的;可变通的', 'Many people prefer more flexible work hours.', '许多人更喜欢更灵活的工作时间。', 'Morals and Virtues', 33, 0, 'senior', 'wordlist', 'required3', 'U2', 'flexible hours', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'scare', 'vt./vi.', '/skeə(r)/', '惊吓;使害怕;受惊吓', 'The sudden noise scared the little child.', '突如其来的声响吓到了那个小孩。', 'Morals and Virtues', 34, 0, 'senior', 'wordlist', 'required3', 'U2', 'scare sb', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'scared', 'adj.', '/skeəd/', '害怕的;惊慌的', 'She was so scared during the interview that she forgot her words.', '面试时她吓得忘了要说的话。', 'Morals and Virtues', 35, 0, 'senior', 'wordlist', 'required3', 'U2', 'be scared', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'whisper', 'vi./vt./n.', '/ˈwɪspə(r)/', '悄声说;耳语;低语;耳语声', 'I saw her whispering something into his ear.', '我看见她在他耳边低声说着什么。', 'Morals and Virtues', 36, 0, 'senior', 'wordlist', 'required3', 'U2', 'whisper something', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'faint', 'vi./adj.', '/feɪnt/', '昏倒;晕厥;微弱的;不清楚的', 'During the exam, the student next to her fainted.', '考试时,坐在她旁边的学生晕倒了。', 'Morals and Virtues', 37, 0, 'senior', 'wordlist', 'required3', 'U2', 'faint during the exam', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'clinic', 'n.', '/ˈklɪnɪk/', '诊所;门诊部', 'Dr Lin opened a private clinic to help the poor.', '林大夫开了一家私人诊所来帮助穷人。', 'Morals and Virtues', 38, 0, 'senior', 'wordlist', 'required3', 'U2', 'open a clinic', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'physician', 'n.', '/fɪˈzɪʃn/', '医师;(尤指)内科医生', 'She became the first woman hired as a resident physician.', '她成为首位被聘为住院医师的女性。', 'Morals and Virtues', 39, 0, 'senior', 'wordlist', 'required3', 'U2', 'a resident physician', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'operation', 'n.', '/ˌɒpəˈreɪʃn/', '手术;企业;经营', 'During the operation, she waited anxiously for over an hour.', '手术期间,她焦急地等了一个多小时。', 'Morals and Virtues', 40, 0, 'senior', 'wordlist', 'required3', 'U2', 'during the operation', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'first aid', 'n.', '/ˌfɜːst ˈeɪd/', '急救', 'He showed the villagers how to give first aid.', '他向村民们示范如何进行急救。', 'Morals and Virtues', 41, 0, 'senior', 'wordlist', 'required3', 'U2', 'give first aid', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'colleague', 'n.', '/ˈkɒliːɡ/', '同事;同僚', 'She greatly impressed her American colleagues.', '她给美国同事留下了深刻印象。', 'Morals and Virtues', 42, 0, 'senior', 'wordlist', 'required3', 'U2', 'impress colleagues', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'staff', 'n.', '/stɑːf/', '员工;全体职员', 'She told her new staff to treat patients as sisters.', '她叮嘱新职员要把病人当作姐妹对待。', 'Morals and Virtues', 43, 0, 'senior', 'wordlist', 'required3', 'U2', 'tell the staff', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'income', 'n.', '/ˈɪnkʌm/', '收入;收益', 'Many doctors felt their income did not match their hard work.', '许多医生觉得收入与付出不相称。', 'Morals and Virtues', 44, 0, 'senior', 'wordlist', 'required3', 'U2', 'a low income', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'tension', 'n.', '/ˈtenʃn/', '紧张关系;紧张;焦虑', 'Some reports increased the tension between doctors and patients.', '一些报道加剧了医患之间的紧张关系。', 'Morals and Virtues', 45, 0, 'senior', 'wordlist', 'required3', 'U2', 'tension between', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'therefore', 'adv.', '/ˈðeəfɔː(r)/', '因此;所以', 'She charged low fees, and therefore the poor could see a doctor.', '她收费很低,因此穷人也能看上病。', 'Morals and Virtues', 46, 0, 'senior', 'wordlist', 'required3', 'U2', 'and therefore', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'fable', 'n.', '/ˈfeɪbl/', '寓言;寓言故事', 'The teacher asked us to write a review of a moral fable.', '老师让我们写一篇道德寓言的评论。', 'Morals and Virtues', 47, 0, 'senior', 'wordlist', 'required3', 'U2', 'a moral fable', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'decade', 'n.', '/ˈdekeɪd/', '十年;十年期', 'Over the next several decades, she held many important positions.', '在随后的几十年里,她担任过许多重要职务。', 'Morals and Virtues', 48, 0, 'senior', 'wordlist', 'required3', 'U2', 'over the decades', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'pass away', 'phr.', '/pɑːs əˈweɪ/', '去世', 'Dr Bethune passed away while serving the Chinese people.', '白求恩大夫在为中国人民服务时去世了。', 'Morals and Virtues', 49, 0, 'senior', 'wordlist', 'required3', 'U2', 'pass away', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'scholarship', 'n.', '/ˈskɒləʃɪp/', '奖学金', 'She graduated with the highest scholarship given to graduates.', '她以授予毕业生的最高奖学金毕业。', 'Morals and Virtues', 50, 0, 'senior', 'wordlist', 'required3', 'U2', 'win a scholarship', NULL);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('r3u2.01', '①V-ing 作时间/原因状语(= When/Because + 主语…)', 'A2', 10, '必修三 U2 — 现在分词放句首或句中,表示与主句同时或在先的动作/原因,逻辑主语 = 主句主语,且该主语主动发出动作时用 V-ing(Hearing the news, he rushed out.)。', 1, 'required3', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('r3u2.02', '②V-ing 作伴随/结果状语', 'A2', 10, '必修三 U2 — 现在分词表示与主句谓语同时发生的伴随动作,或自然而然产生的结果,常置于句末(She sat there, smiling. / The flood hit the town, leaving thousands homeless.),逻辑主语仍是主句主语。', 2, 'required3', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('r3u2.03', '③see/hear/watch/find + sb + doing(宾补,主动进行) vs done(被动)', 'A2', 10, '必修三 U2 — 感官动词及 find 后接现在分词作宾补,强调宾语正在主动进行动作(I saw her whispering.);若宾语是动作的承受者则用过去分词 done(I saw the work done.)。', 3, 'required3', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.01'), '____ the news that her mother had died, the little girl burst into tears.', 'Hearing', 'To hear', 'Heard', 'Having heard', 'A', '逻辑主语 girl 主动''听到''、与哭泣几乎同时 → 现在分词 Hearing 作时间状语。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.01'), '____ of all the people still in need of help, Dr Lin opened a private clinic.', 'To think', 'Thinking', 'Thought', 'Be thinking', 'B', 'Dr Lin 主动''想到'',表原因 → Thinking。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.01'), '____ that his wife had been injured, Mr Johnson hurried to the hospital.', 'To hear', 'Heard', 'Hearing', 'Hear', 'C', 'Mr Johnson 主动听说、表原因 → 现在分词 Hearing。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.01'), '____ the high tuition fees, her brother thought she should not study so much.', 'To think of', 'Thought of', 'Think of', 'Thinking of', 'D', 'brother 主动''想到''学费、表原因 → Thinking of。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.01'), '____ higher import and export costs, the company is looking for ways to survive.', 'Facing', 'To face', 'Faced', 'Face', 'A', 'the company 主动''面对''成本、表原因 → 现在分词 Facing。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.01'), '____ from the North Pole, the traveller wrote a book about his experience.', 'To return', 'Returning', 'Returned', 'Return', 'B', 'traveller 主动''返回''、表时间(回来之后)→ Returning。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.01'), '____ the gold coins, the girl was greatly surprised but did not keep them.', 'To see', 'Seen', 'Seeing', 'See', 'C', 'girl 主动''看见''、表时间 → Seeing。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.01'), '____ that many people were dying in the war, Dr Bethune left for China.', 'To hear', 'Heard', 'Hear', 'Hearing', 'D', 'Bethune 主动''听说''、表原因 → Hearing。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.01'), '____ that nothing good came from complaints, the king decided to teach a lesson.', 'Believing', 'To believe', 'Believed', 'Believe', 'A', 'the king 主动''认为''、表原因 → Believing。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.01'), '____ deeply by her mother''s death, Lin Qiaozhi later chose to study medicine.', 'Affecting', 'Affected', 'To affect', 'Affect', 'B', '逻辑主语 Lin ''被''母亲去世所影响,是动作承受者 → 过去分词 Affected(本题对照被动用法)。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.01'), '____ a stone in the road, the girl knew it was dangerous to others after dark.', 'To notice', 'Noticed', 'Noticing', 'Notice', 'C', 'girl 主动''注意到''、表时间 → Noticing。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.01'), '____ to give up her dream, she told her brother she would rather stay single to study.', 'To refuse', 'Refused', 'Refuse', 'Refusing', 'D', 'she 主动''拒绝''、表原因 → Refusing。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.01'), '____ how kind the lady had been, the waitress decided to pass the kindness on.', 'Remembering', 'To remember', 'Remembered', 'Remember', 'A', 'waitress 主动''记得''、表原因 → Remembering。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.01'), '____ his savings to a kindergarten, the old doctor felt at peace.', 'To leave', 'Leaving', 'Left', 'Leave', 'B', 'the doctor 主动''留下''积蓄、表时间/伴随原因 → Leaving。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.01'), '____ low fees from poor patients, the kind doctor was loved by the whole town.', 'To charge', 'Charged', 'Charging', 'Charge', 'C', 'the doctor 主动''收取''、表原因 → Charging。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.01'), '____ that the department had been closed, she set up a clinic of her own.', 'To know', 'Known', 'Know', 'Knowing', 'D', 'she 主动''知道''、表原因 → Knowing。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.01'), '____ the same dilemma as the girl, many students could not decide what to do.', 'Facing', 'To face', 'Faced', 'Face', 'A', 'students 主动''面临''、表时间/原因 → Facing。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.01'), '____ on a donkey to faraway villages, she brought medical care to the poor.', 'To ride', 'Riding', 'Ridden', 'Ride', 'B', 'she 主动''骑''驴、表时间 → Riding。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.01'), '____ how hard it was to help others, he still chose to volunteer every weekend.', 'To understand', 'Understood', 'Understanding', 'Understand', 'C', 'he 主动''明白''、表原因(让步)→ Understanding。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.01'), '____ a kind note under the change, the lady quietly left the café.', 'To leave', 'Left', 'Leave', 'Leaving', 'D', 'the lady 主动''留下''纸条、表时间 → Leaving。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.02'), 'The child lay on her mother''s lap, ____ sweetly to herself.', 'smiling', 'to smile', 'smiled', 'smile', 'A', '句末伴随状语,child 主动''微笑''与 lay 同时 → 现在分词 smiling。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.02'), 'She sat in the waiting room for over an hour, ____ about him.', 'to worry', 'worrying', 'worried', 'worry', 'B', '句末伴随状语,she 主动''担心''与 sat 同时 → worrying。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.02'), 'The milkman crashed into the stone, ____ the milk everywhere.', 'to spill', 'spilt', 'spilling', 'spill', 'C', '结果状语,自然导致牛奶洒出 → 现在分词 spilling。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.02'), 'The flood hit the small town, ____ thousands of families homeless.', 'to leave', 'left', 'leave', 'leaving', 'D', '结果状语,洪水自然''使……无家可归''→ leaving。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.02'), 'He walked out of the café, ____ a note and the change for the waitress.', 'leaving', 'to leave', 'left', 'leave', 'A', '伴随状语,he 主动''留下''与 walked 同时 → leaving。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.02'), 'Dr Lin worked day and night, ____ over 50,000 babies in her lifetime.', 'to deliver', 'delivering', 'delivered', 'deliver', 'B', '结果/伴随状语,主动''接生'' → delivering。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.02'), 'The girl pushed the stone with all her might, finally ____ in moving it aside.', 'to succeed', 'succeeded', 'succeeding', 'succeed', 'C', '结果状语,自然导致''成功'' → succeeding。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.02'), 'She picked herself up and limped away, ____ quietly all the way home.', 'to cry', 'cried', 'cry', 'crying', 'D', '伴随状语,she 主动''哭''与 limped 同时 → crying。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.02'), 'The kind lady drove off, ____ the young waitress full of hope.', 'leaving', 'to leave', 'left', 'leave', 'A', '结果状语 → leaving。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.02'), 'He stood in front of the class, completely ____ the speech he had prepared.', 'to forget', 'forgetting', 'forgotten', 'forget', 'B', '伴随状语,he 主动''忘记''与 stood 同时 → forgetting。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.02'), 'Dr Bethune travelled from village to village, ____ doctors and nurses on the way.', 'to train', 'trained', 'training', 'train', 'C', '伴随状语,主动''培训'' → training。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.02'), 'The old man sat by the fire, ____ stories of kindness to the children.', 'to tell', 'told', 'tell', 'telling', 'D', '伴随状语,主动''讲''与 sat 同时 → telling。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.02'), 'The good news spread quickly through the town, ____ everyone hope again.', 'giving', 'to give', 'given', 'give', 'A', '结果状语 → giving。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.02'), 'She bit her lip and walked away in silence, ____ to show her tears.', 'to refuse', 'refusing', 'refused', 'refuse', 'B', '伴随状语,主动''拒绝'' → refusing。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.02'), 'The doctor reduced the costs again and again, often ____ nothing from the poor.', 'to charge', 'charged', 'charging', 'charge', 'C', '伴随状语,主动''收取'' → charging。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.02'), 'The young farmer''s daughter rolled the stone aside, ____ the road safe for all.', 'to make', 'made', 'make', 'making', 'D', '结果状语,自然''使道路安全'' → making。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.02'), 'The whole village watched in silence, slowly ____ the meaning of her act.', 'understanding', 'to understand', 'understood', 'understand', 'A', '伴随状语,主动''明白'' → understanding。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.02'), 'He helped to organise hospitals, ____ people how to give first aid.', 'to show', 'showing', 'shown', 'show', 'B', '伴随状语,主动''示范'' → showing。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.02'), 'The chain of kindness went on and on, ____ from one stranger to the next.', 'to pass', 'passed', 'passing', 'pass', 'C', '伴随状语,主动''传递'' → passing。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.02'), 'The kind act warmed the whole town, ____ a small fire of hope in every heart.', 'to light', 'lit', 'light', 'lighting', 'D', '结果状语 → lighting。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.03'), 'I saw her ____ something into his ear, obviously not wanting to be heard.', 'whispering', 'whispered', 'to whisper', 'whisper to', 'A', 'see sb doing:宾语 her 主动''低语''、强调正在进行 → whispering。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.03'), 'The new People''s Republic of China saw Dr Lin ____ a key role in medicine.', 'played', 'playing', 'to play', 'play with', 'B', 'see sb doing:Dr Lin 主动''发挥''作用 → playing。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.03'), 'He suddenly woke up when he heard someone ____ at his door.', 'knocked', 'to knock', 'knocking', 'knock on by', 'C', 'hear sb doing:someone 主动''敲门''、进行中 → knocking。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.03'), 'Seeing the tennis star ____ the court, the girl quickly picked up her camera.', 'left', 'to leave', 'leave for', 'leaving', 'D', 'see sb doing:the star 主动''离开''球场 → leaving。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.03'), 'John watched the woman ____ to the air, thinking she might be unwell.', 'talking', 'talked', 'to talk', 'talk by', 'A', 'watch sb doing:the woman 主动''说话''、进行中 → talking。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.03'), 'The king watched all day but found nobody ____ to move the stone.', 'tried', 'trying', 'to be tried', 'be tried', 'B', 'find sb doing:nobody 主动''尝试''、进行中 → trying。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.03'), 'At times Dr Lin was even seen ____ a donkey to faraway villages.', 'ridden', 'rode', 'riding', 'to riding', 'C', 'be seen doing(被动后保留 doing):Dr Lin 主动''骑''驴 → riding。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.03'), 'We watched the milk ____ all over the street after the cart crashed.', 'spilt', 'to spill', 'spill over by', 'spilling', 'D', 'watch sth doing:milk 主动''流淌''、进行中 → spilling。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.03'), 'They were very proud to see their son ____ the university scholarship.', 'awarded', 'awarding', 'to award', 'award', 'A', 'see sb done:son 是''被授予''奖学金的承受者 → 过去分词 awarded(对照被动)。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.03'), 'She heard the children ____ happily in the next room and smiled.', 'laughed', 'laughing', 'to laugh', 'laugh at by', 'B', 'hear sb doing:children 主动''笑''、进行中 → laughing。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.03'), 'The crowd watched the young girl ____ the heavy stone with all her might.', 'pushed', 'to push', 'pushing', 'push by', 'C', 'watch sb doing:girl 主动''推''、进行中 → pushing。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.03'), 'I found my little brother ____ over an old fable, deeply moved by the story.', 'cried', 'to cry', 'cry by', 'crying', 'D', 'find sb doing:brother 主动''哭''、进行中 → crying。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.03'), 'The manager was pleased to find the job already ____ when he arrived.', 'done', 'doing', 'to do', 'do', 'A', 'find sth done:the job 是''被完成''的承受者 → 过去分词 done(对照被动)。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.03'), 'The nurse saw tears ____ down the patient''s face and gently held her hand.', 'run', 'running', 'to run', 'ran', 'B', 'see sth doing:tears 主动''流淌''、进行中 → running。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.03'), 'He heard his name ____ across the hall just as he was about to leave.', 'calling', 'to call', 'called', 'call', 'C', 'hear sth done:his name 是''被叫''的承受者 → 过去分词 called(对照被动)。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.03'), 'We could see the kind doctor ____ patients late into the night.', 'tended', 'to tend', 'tend by', 'tending', 'D', 'see sb doing:doctor 主动''照料''、进行中 → tending。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.03'), 'She watched the lady ____ the change behind for the tired waitress.', 'leaving', 'left', 'to leave', 'leave by', 'A', 'watch sb doing:lady 主动''留下''、进行中 → leaving。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.03'), 'The teacher found the whole class ____ in tears at the end of the sad story.', 'sat', 'sitting', 'to sit', 'sit by', 'B', 'find sb doing:class 主动''坐着''、状态进行中 → sitting。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.03'), 'The villagers saw the road ____ at last, thanks to one girl''s kindness.', 'clearing', 'to clear', 'cleared', 'clear', 'C', 'see sth done:the road 是''被清理''的承受者 → 过去分词 cleared(对照被动)。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required3' AND unit='U2' AND code='r3u2.03'), 'I often hear people ____ about small problems but doing nothing to fix them.', 'complained', 'to complain', 'complain by', 'complaining', 'D', 'hear sb doing:people 主动''抱怨''、进行中 → complaining。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'A Life of Hard Choices', 'Dr Lin Qiaozhi once said that nothing is more precious to a person than their life. These words give us a look into the heart of an amazing woman. As a young girl, she was deeply affected by her mother''s early death. At the age of eighteen, instead of following the path of marriage like most girls, she chose to study medicine. Her brother complained about the high cost, asking why a girl should learn so much when her real goal was to find a good husband. She answered that she would rather stay single and study all her life. Eight years later she graduated from medical college with the highest prize given to students. She at once became the first woman ever hired as a resident physician in her department. Within only six months she was named a chief resident, a position that usually took four years. Every choice she made put helping others above an easy, comfortable life.', 'Morals and Virtues', 160, '[{"q":"Why did Lin Qiaozhi''s brother complain when she chose medicine?","answer":"A","options":["He believed a girl''s main aim ought to be marriage.","He wanted her to become a teacher instead.","He thought medicine was dangerous for women.","He hoped she would study abroad."],"explanation":"原文哥哥抱怨女孩学那么多没用、目标应是嫁个好丈夫的转述。"},{"q":"How did Lin respond to her brother''s complaint?","answer":"B","options":["She agreed to give up her studies.","She said she would rather remain single and keep studying.","She asked her family for more money.","She decided to marry first and study later."],"explanation":"原文 ''rather stay single to study all my life'' 的转述。"},{"q":"What does the writer want to show by describing her early career?","answer":"A","options":["That serving others always mattered more to her than comfort.","That she was unlucky in her work.","That she cared more about money than patients.","That she regretted not getting married."],"explanation":"末句概括:每个选择都把助人置于舒适生活之上。"}]'::jsonb, '[{"word":"precious","cn":"宝贵的"},{"word":"physician","cn":"内科医生"},{"word":"majority","cn":"大多数"}]'::jsonb, 2, 'required3', 'U2');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'The Mother of Ten Thousand Babies', 'When the new China was founded, Dr Lin played a key role in medicine. In 1954 she was elected to the National People''s Congress, and over the next several decades she held many important positions. Yet her heart was always elsewhere. She was far more interested in caring for patients, in publishing research on the health of women and children, and in training young doctors. She reminded her staff that their department cared for two lives at once, and that doctors should treat patients as their own sisters. Though she never married, she became known as the mother of ten thousand babies, for she had helped to deliver more than fifty thousand children. She kept working right up to the day she died in 1983. Having no children of her own, she gave her savings to a kindergarten and to a fund for new doctors. Even as she lay dying, her last thoughts were not for herself but for others.', 'Morals and Virtues', 160, '[{"q":"What was Dr Lin most interested in, even while holding high positions?","answer":"B","options":["Becoming famous across the country.","Caring for patients and training young doctors.","Earning a higher income each year.","Travelling abroad to study."],"explanation":"原文她更在意照料病人、发表研究、培养医生的转述。"},{"q":"Why was she called ''the mother of ten thousand babies''?","answer":"C","options":["Because she had ten thousand children of her own.","Because she ran a famous kindergarten.","Because she helped bring over fifty thousand babies into the world.","Because she wrote books for mothers."],"explanation":"原文 ''delivered over 50,000 babies'' 的转述。"},{"q":"What does her final wish tell us about her character?","answer":"D","options":["She was afraid of dying alone.","She regretted her career choices.","She wanted to be remembered as rich.","She was thinking of others rather than herself."],"explanation":"末句概括:临终所想皆为他人。"}]'::jsonb, '[{"word":"elect","cn":"选举"},{"word":"publish","cn":"发表"},{"word":"saving","cn":"积蓄"}]'::jsonb, 2, 'required3', 'U2');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'Dr Bethune in China', 'Henry Norman Bethune was a Canadian doctor with a creative mind and a strong wish to help people. Even as a small boy, he grew interested in medicine and decided to become a doctor. After finishing medical college, he worked in England, the United States and Canada, where he redesigned more than ten medical tools to make them more useful. In 1938, having learnt that many people were dying in the war, he left his home and travelled to China. The situation was difficult, but he did whatever he could for the Chinese people. He helped to set up hospitals, taught local doctors and nurses, and showed ordinary people how to give first aid. Sadly, he passed away the following year and was buried in Shijiazhuang. After his death, an article was written in his memory, praising him as a hero whose unselfish spirit would always be remembered in China.', 'Morals and Virtues', 150, '[{"q":"What did Bethune do with medical tools before coming to China?","answer":"A","options":["He improved more than ten of them.","He sold them to hospitals abroad.","He refused to use any of them.","He invented machines for factories."],"explanation":"原文 ''redesigned over 10 medical instruments'' 的转述。"},{"q":"Why did Bethune decide to travel to China?","answer":"B","options":["He wanted a long holiday there.","He learnt that war was killing many people.","He was sent by his government.","He wished to study Chinese medicine."],"explanation":"原文 ''heard that many people were dying in the war'' 的转述。"},{"q":"How is Bethune remembered in China?","answer":"C","options":["As a rich businessman.","As a doctor who cared only about money.","As a hero with an unselfish spirit.","As an unlucky traveller."],"explanation":"末句把他赞为应被铭记的英雄,概括其无私精神。"}]'::jsonb, '[{"word":"first aid","cn":"急救"},{"word":"pass away","cn":"去世"},{"word":"publish","cn":"发表"}]'::jsonb, 2, 'required3', 'U2');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'The Stone in the Road', 'Long ago a king worried that his people only complained and waited for others to solve their problems. Early one morning he disguised himself and went to a village. He placed a large stone in the middle of the main street and hid some gold coins beneath it. Then he hid behind a tree to watch. A milkman crashed into the stone and shouted angrily before going away. A group of women came by, and one tripped over it and limped off in tears, yet none of them moved it. All day people complained, but nobody tried to clear the road. At last a tired farmer''s daughter came along. Seeing that the stone was a danger to others after dark, she pushed it aside with all her might. To her surprise she found the gold beneath it. When the king stepped out, she offered to find the owner, not knowing the gift was now hers.', 'Morals and Virtues', 155, '[{"q":"Why did the king put a stone in the road?","answer":"D","options":["To block traffic for a festival.","To make people angry at one another.","To hide the gold from thieves forever.","To test whether anyone would take responsibility."],"explanation":"全文寓意:国王想检验是否有人愿担起责任搬开石头。"},{"q":"How did most of the villagers react to the stone?","answer":"A","options":["They complained but left it where it was.","They quickly moved it aside.","They reported it to the king.","They took the gold and ran away."],"explanation":"原文众人只抱怨、无人去搬的转述。"},{"q":"What was special about the young girl''s response?","answer":"B","options":["She was the only one who saw the stone.","She thought of others'' safety and acted.","She wanted the gold from the start.","She was ordered by the king to move it."],"explanation":"原文她想到石头夜里危险、主动搬开的转述。"}]'::jsonb, '[{"word":"disguise","cn":"假扮"},{"word":"trip over","cn":"被绊倒"},{"word":"limp","cn":"一瘸一拐地走"}]'::jsonb, 2, 'required3', 'U2');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'The Chain of Love', 'There is a famous song about a chain of kindness that passes from one stranger to another. It begins with a man who stops to help a lady whose car has broken down on a lonely road. When the grateful lady tries to pay him, he refuses the money and asks her only to help someone else in the same way. A little later the lady stops at a small café, where she notices that the tired waitress is going to have a baby soon. After her meal, the lady pays the bill and quietly leaves behind some extra money and a note. The note asks the waitress to keep the chain of kindness going. The story has a warm ending: the waitress goes home to her husband, cheered by the stranger''s care. In the last line we learn that her husband was the very man who first started the chain of love.', 'Morals and Virtues', 153, '[{"q":"What did the man ask the lady to do instead of paying him?","answer":"C","options":["To tell others about his shop.","To send him a thank-you letter.","To pass on the kindness to someone else.","To pay double the next time."],"explanation":"原文他不收钱、只让她帮助别人的转述。"},{"q":"Why did the lady leave extra money for the waitress?","answer":"D","options":["She had eaten too much food.","She wanted to buy something later.","She had paid the wrong bill.","She noticed the waitress was tired and expecting a baby."],"explanation":"原文她注意到女服务员疲惫又怀孕的转述。"},{"q":"What is surprising about the ending of the story?","answer":"A","options":["The waitress''s husband had started the whole chain.","The lady never paid for her meal.","The man had been rich all along.","The waitress did not have a baby."],"explanation":"末句揭示:她丈夫正是最先发起善意链条的人。"}]'::jsonb, '[{"word":"respond","cn":"回应"},{"word":"waitress","cn":"女服务员"},{"word":"pregnant","cn":"怀孕的"}]'::jsonb, 2, 'required3', 'U2');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'Virtues We Cherish', 'Every culture admires certain virtues. Honesty, courage, generosity and thankfulness are praised by people all over the world, no matter where they live. A virtue is not a grand act done only once. As one poet wrote, the best part of a good person''s life is made up of small, nameless acts of kindness that nobody remembers. Sometimes living by our values means facing a moral dilemma, where every choice is hard. Should you tell the truth even when it costs you a friend? Should you help a stranger when you are tired and busy? There are no easy answers, but the people we most admire are those who choose what is right rather than what is easy. Thankfulness, too, shapes how we see the world. When we are grateful for what we have, we tend to give more to others. In this way, small virtues practised every day can slowly make a whole society kinder.', 'Morals and Virtues', 156, '[{"q":"According to the poet, what makes up the best part of a good person''s life?","answer":"B","options":["A few famous and grand achievements.","Small unremembered acts of kindness.","The money they give to charity.","The honours they receive."],"explanation":"原文诗句关于无名小善的转述。"},{"q":"What does a moral dilemma usually involve?","answer":"C","options":["An easy choice between right and wrong.","A problem only doctors can solve.","A situation where every choice is difficult.","A test set by the government."],"explanation":"原文道德困境=每个选择都很难的转述。"},{"q":"What does the writer say about thankfulness?","answer":"D","options":["It is the hardest virtue to learn.","It matters only to rich people.","It has nothing to do with kindness.","It makes people give more to others."],"explanation":"原文感恩使人更愿付出的转述。"}]'::jsonb, '[{"word":"virtue","cn":"美德"},{"word":"dilemma","cn":"困境"},{"word":"tend","cn":"倾向于"}]'::jsonb, 2, 'required3', 'U2');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required3', 'U2', 'A Difficult Choice in the Exam', 'During an important exam, the girl next to me suddenly turned pale and (1)____ to the floor. For a moment I was caught in a real (2)____. If I helped her, I might lose my own chance; if I did nothing, she might be in (3)____. My heart told me that a person''s life is more (4)____ than any test. So I stood up and called for (5)____. The teachers carried her out, and later I learned she was safe. I had to (6)____ the rest of the paper in a hurry and my marks were not high. Yet I never (7)____ my choice. Doing the right thing sometimes (8)____ a price, but I would rather pay it than ignore someone in (9)____. That day taught me what it really means to live by your (10)____.', 136, 2, '[{"q":"1","answer":"A","options":["fell","smiled","sang","ran"],"explanation":"fell to the floor 倒在地上。"},{"q":"2","answer":"B","options":["holiday","dilemma","garden","market"],"explanation":"a real dilemma 真正的困境。"},{"q":"3","answer":"C","options":["love","music","danger","fashion"],"explanation":"in danger 处于危险中。"},{"q":"4","answer":"D","options":["cheap","loud","heavy","precious"],"explanation":"more precious 更宝贵。"},{"q":"5","answer":"A","options":["help","food","money","paper"],"explanation":"call for help 呼救。"},{"q":"6","answer":"B","options":["sell","finish","throw","hide"],"explanation":"finish the paper 做完试卷。"},{"q":"7","answer":"C","options":["enjoyed","sold","regretted","forgot"],"explanation":"never regretted 从不后悔。"},{"q":"8","answer":"D","options":["loses","breaks","leaves","costs"],"explanation":"costs a price 付出代价。"},{"q":"9","answer":"A","options":["need","fun","music","sport"],"explanation":"someone in need 需要帮助的人。"},{"q":"10","answer":"B","options":["bags","values","shoes","phones"],"explanation":"live by your values 按价值观生活。"}]'::jsonb, 1);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required3', 'U2', 'Choosing to Study Medicine', 'When my grandmother was young, she made a brave (1)____. Most girls of her age planned only to marry, but she wanted to (2)____ medicine. Her family (3)____ about the high cost and said a girl did not need so much learning. She answered that she would rather stay (4)____ and study all her life. After years of hard work, she (5)____ from college with a top prize. She became one of the first women to be (6)____ as a doctor in her town. Patients who could not pay were never (7)____ away; she often charged them very low (8)____. She believed that no one should be (9)____ medical care because they were poor. To me, she will always be a model of what a kind (10)____ should be.', 129, 2, '[{"q":"1","answer":"C","options":["noise","price","choice","song"],"explanation":"a brave choice 勇敢的选择。"},{"q":"2","answer":"D","options":["sell","throw","hide","study"],"explanation":"study medicine 学医。"},{"q":"3","answer":"A","options":["worried","sang","danced","slept"],"explanation":"worried about 担心。"},{"q":"4","answer":"B","options":["rich","single","loud","late"],"explanation":"stay single 保持单身。"},{"q":"5","answer":"C","options":["ran","ate","graduated","fell"],"explanation":"graduated from college 大学毕业。"},{"q":"6","answer":"D","options":["lost","sold","broken","hired"],"explanation":"be hired 被聘用。"},{"q":"7","answer":"A","options":["turned","flown","sung","eaten"],"explanation":"turned away 被赶走/拒之门外。"},{"q":"8","answer":"B","options":["games","fees","songs","noises"],"explanation":"low fees 低廉的费用。"},{"q":"9","answer":"C","options":["thanked","praised","refused","invited"],"explanation":"be refused care 被拒绝提供照顾。"},{"q":"10","answer":"D","options":["price","city","machine","doctor"],"explanation":"a kind doctor 善良的医生。"}]'::jsonb, 2);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required3', 'U2', 'Helping a Stranger', 'One cold evening, I saw an old man (1)____ by the road with a broken bag of shopping. Most people walked past without a (2)____, but I stopped to help. Together we picked up his apples and I (3)____ his bag home for him. He wanted to give me some (4)____, but I refused and asked him only to (5)____ kindness on to someone else. He smiled and said that a small act of (6)____ can travel further than we think. A week later, I was (7)____ in the rain when a young woman shared her umbrella with me. She told me a stranger had once helped her, so now she liked to (8)____ others too. At that moment I understood the (9)____ of love that quietly connects us all. Kindness, I learned, is never (10)____; it always comes back.', 140, 2, '[{"q":"1","answer":"A","options":["standing","flying","swimming","driving"],"explanation":"standing by the road 站在路边。"},{"q":"2","answer":"B","options":["price","word","noise","song"],"explanation":"without a word 一言不发。"},{"q":"3","answer":"C","options":["sold","ate","carried","lost"],"explanation":"carried his bag 帮他提包。"},{"q":"4","answer":"D","options":["games","songs","noises","money"],"explanation":"give me money 给我钱。"},{"q":"5","answer":"A","options":["pass","throw","sell","hide"],"explanation":"pass kindness on 把善意传下去。"},{"q":"6","answer":"B","options":["price","kindness","noise","weather"],"explanation":"an act of kindness 善举。"},{"q":"7","answer":"C","options":["sleeping","singing","caught","eating"],"explanation":"be caught in the rain 被雨淋。"},{"q":"8","answer":"D","options":["forget","leave","lose","help"],"explanation":"help others 帮助他人。"},{"q":"9","answer":"A","options":["chain","price","noise","machine"],"explanation":"the chain of love 爱的链条。"},{"q":"10","answer":"B","options":["bright","wasted","loud","heavy"],"explanation":"never wasted 从不白费。"}]'::jsonb, 3);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required3', 'U2', 'The Lesson of the Stone', 'A wise king once grew tired of people who only (1)____ and waited for others to act. To teach them a lesson, he (2)____ himself as a poor traveller and placed a heavy stone in the middle of a busy (3)____. All day, people (4)____ over the stone or shouted at it, but no one moved it out of the (5)____. The king watched in (6)____, wondering if anyone cared about their neighbours. At last a tired farm girl came by. Seeing that the stone was a (7)____ to others in the dark, she pushed it aside with all her (8)____. Beneath it she found a bag of gold, but she at once offered to find the (9)____. The king smiled and gave her the gold, for she alone had learned the (10)____ he wished to teach.', 137, 2, '[{"q":"1","answer":"C","options":["sang","danced","complained","slept"],"explanation":"only complained 只会抱怨。"},{"q":"2","answer":"D","options":["sold","lost","broke","disguised"],"explanation":"disguised himself 假扮自己。"},{"q":"3","answer":"A","options":["street","sky","river","cloud"],"explanation":"a busy street 繁忙的街道。"},{"q":"4","answer":"B","options":["flew","tripped","swam","drove"],"explanation":"tripped over 被绊倒。"},{"q":"5","answer":"C","options":["sea","sky","road","air"],"explanation":"out of the road 移出路面。"},{"q":"6","answer":"D","options":["joy","music","sport","despair"],"explanation":"in despair 绝望地。"},{"q":"7","answer":"A","options":["danger","gift","song","price"],"explanation":"a danger to others 对他人的危险。"},{"q":"8","answer":"B","options":["money","might","paper","food"],"explanation":"with all her might 用尽全力。"},{"q":"9","answer":"C","options":["noise","price","owner","weather"],"explanation":"find the owner 找到主人。"},{"q":"10","answer":"D","options":["price","noise","game","lesson"],"explanation":"the lesson 教训。"}]'::jsonb, 4);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required3', 'U2', 'A Grateful Heart', 'My teacher once told us that thankfulness is a (1)____ that can change a whole life. She said many people only (2)____ about what they do not have, and so they never feel (3)____. But if we are grateful for what we already (4)____, we tend to be happier and to give (5)____ to others. To help us understand, she shared an old (6)____: a man who had no shoes felt sorry for himself until he met a man with no (7)____. That meeting taught him to count his (8)____ instead of his troubles. Since then, I have tried to (9)____ the people around me every day — my parents, my friends, even a stranger who holds a door open. A grateful heart, I have found, makes the world look much (10)____.', 132, 2, '[{"q":"1","answer":"A","options":["virtue","price","noise","machine"],"explanation":"a virtue 一种美德。"},{"q":"2","answer":"B","options":["sing","complain","dance","sleep"],"explanation":"complain about 抱怨。"},{"q":"3","answer":"C","options":["tall","loud","enough","late"],"explanation":"feel enough 感到满足。"},{"q":"4","answer":"D","options":["sell","throw","lose","have"],"explanation":"what we have 我们拥有的。"},{"q":"5","answer":"A","options":["more","less","later","louder"],"explanation":"give more 付出更多。"},{"q":"6","answer":"B","options":["price","saying","noise","machine"],"explanation":"an old saying 一句古老的格言。"},{"q":"7","answer":"C","options":["books","cars","feet","phones"],"explanation":"no feet 没有脚。"},{"q":"8","answer":"D","options":["mistakes","errors","noises","blessings"],"explanation":"count his blessings 数算所拥有的福气。"},{"q":"9","answer":"A","options":["thank","forget","leave","lose"],"explanation":"thank the people 感谢身边的人。"},{"q":"10","answer":"B","options":["worse","brighter","darker","smaller"],"explanation":"look brighter 看起来更明亮。"}]'::jsonb, 5);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required3', 'U2', 'The Doctor Who Never Stopped', 'In a small mountain town there lived a doctor (1)____ everyone loved. He had once been offered a good job in a big city, but he (2)____ it so that he could serve the poor at home. Every day he (3)____ patients from morning until midnight, and he never (4)____ about the long hours. When families could not pay, he quietly (5)____ the cost or treated them for free. People often saw him (6)____ on an old bike to faraway villages, his bag full of medicine. He believed that a doctor should (7)____ patients as members of his own family. Even after he was old, he did not (8)____, saying his work was not yet (9)____. When he finally passed away, the whole town came to thank him, for his kindness had (10)____ countless lives.', 135, 2, '[{"q":"1","answer":"C","options":["which","where","whom","when"],"explanation":"a doctor whom everyone loved 人人爱戴的医生(指人作宾语)。"},{"q":"2","answer":"D","options":["bought","sold","lost","rejected"],"explanation":"rejected it 拒绝了它。"},{"q":"3","answer":"A","options":["tended","sold","ate","threw"],"explanation":"tended patients 照料病人。"},{"q":"4","answer":"B","options":["sang","complained","danced","slept"],"explanation":"never complained 从不抱怨。"},{"q":"5","answer":"C","options":["raised","sold","reduced","lost"],"explanation":"reduced the cost 降低费用。"},{"q":"6","answer":"D","options":["flying","swimming","sailing","riding"],"explanation":"riding on a bike 骑车。"},{"q":"7","answer":"A","options":["treat","sell","throw","lose"],"explanation":"treat patients as family 把病人当家人。"},{"q":"8","answer":"B","options":["sing","retire","eat","sleep"],"explanation":"did not retire 没有退休。"},{"q":"9","answer":"C","options":["loud","tall","done","heavy"],"explanation":"not yet done 尚未完成。"},{"q":"10","answer":"D","options":["lost","sold","broken","saved"],"explanation":"saved lives 拯救生命。"}]'::jsonb, 6);
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U2 听力·对话 A Moral Dilemma', '必修三 U2 · dialogue', 3, 'Jane: Luke, listen to this story I read in a magazine. It''s about a moral dilemma.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U2 听力·短文 The Power of Kindness', '必修三 U2 · passage', 2, 'A small act of kindness can be more powerful than we think.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U2 听力·对话 Helping a Classmate', '必修三 U2 · dialogue', 3, 'Tom: You look worried, Mary. What''s wrong?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U2 听力·短文 Paying It Forward', '必修三 U2 · passage', 2, 'Welcome to our radio show about everyday heroes.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U2 听力·对话 Virtues We Admire', '必修三 U2 · dialogue', 3, 'Lily: Our teacher asked us to name the virtue we admire most. Which did you choose, Sam?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U2 听力·短文 Counting Your Blessings', '必修三 U2 · passage', 2, 'Thankfulness is one of the simplest yet greatest virtues.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit) VALUES (10, 'Write a Story Praising a Moral Act(写一篇记叙文/表扬信,赞扬一次善举或一位有美德的人)', 'An Act of Kindness I Will Never Forget', '假设你叫李华。上周你亲眼见到(或亲身经历了)一次令你感动的善举。请用英语写一篇约100词的记叙短文(或写给校报的表扬信),内容包括:① 事情发生的时间、地点和背景;② 这个人做了什么(按顺序讲清经过);③ 这件事为什么让你感动,以及它体现了怎样的美德。注意:恰当使用现在分词(V-ing)作状语,如 Seeing the old man fall, …。', 'Suppose you are Li Hua. Last week you saw (or experienced) a moral act that moved you. Write a short story (about 100 words), or a letter of praise to the school newspaper, including: 1) when, where and the background of the event; 2) what the person did, told step by step; 3) why it moved you and what virtue it showed. Try to use the present participle (V-ing) as an adverbial, e.g. ''Seeing the old man fall, …''.', '["交代时间地点背景(Last Friday, on my way home, …)","按顺序讲清经过(First … Then … Finally …)","点明感动之处与体现的美德(What moved me most was … / It showed great kindness)","恰当使用现在分词作状语(Seeing …, / Hearing …, / smiling happily)"]'::jsonb, 70, 100, 'Last Friday, on my way home, I saw something I will never forget. An old man suddenly tripped over a stone and fell to the ground, dropping his bags. Most people just walked past. But a young girl, seeing the old man fall, ran over at once. Kneeling beside him, she gently helped him up and picked up his things. Then she walked him to a bench, smiling warmly all the way. When the old man tried to thank her with money, she refused, asking him only to help someone else one day. What moved me most was her quiet kindness. Her small act showed me that true virtue lies in caring for strangers.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["Seeing the old man fall, a young girl ran over at once.","Kneeling beside him, she gently helped him up and picked up his things.","She walked him to a bench, smiling warmly all the way.","What moved me most was her quiet kindness, which showed true virtue."]'::jsonb, '[{"wrong":"See the old man fall, the girl ran over.","correct":"Seeing the old man fall, the girl ran over.","note":"现在分词作状语要用 V-ing 形式,逻辑主语 = 主句主语 girl。"},{"wrong":"She sat there and smiled, helping him to feel calm.","correct":"She sat there, smiling, which helped him to feel calm.","note":"伴随动作用现在分词 smiling 作状语更地道。"},{"wrong":"What moved me most were her quiet kindness.","correct":"What moved me most was her quiet kindness.","note":"what 引导的主语从句作单数,谓语用 was。"}]'::jsonb, '【赞扬善举记叙文结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content) VALUES (10, 'required3', 'U2', '{"title":"现在分词(V-ing)作状语速查","intro":"现在分词作状语表示与主句相关的动作,可表时间、原因、伴随或结果。判断口诀:逻辑主语 = 主句主语、且主语主动发出动作时用 V-ing(主动/进行);若主语是动作的承受者则用过去分词 done(被动)。","table":{"headers":["用法","例句 / 等价说明"],"rows":[["时间/原因状语","Hearing the news, he rushed out. = When/Because he heard …(主语主动听到)"],["伴随状语","She sat there, smiling happily.(与谓语同时发生的动作)"],["结果状语","The flood hit the town, leaving thousands homeless.(自然产生的结果)"],["see/hear/watch/find + sb + doing","I saw her whispering.(宾语主动进行) ↔ I saw the work done.(被动)"]]},"specialRules":[{"rule":"现在分词的逻辑主语必须 = 主句主语,且主语主动发出动作 → 用 V-ing","mark":"Thinking of the poor, Dr Lin opened a clinic.(Dr Lin 主动 think)"},{"rule":"若主语是动作的承受者(被动),用过去分词 done,不用 V-ing","mark":"Hurt by the rejection, she walked away.(she 被 hurt)"},{"rule":"感官动词 see/hear/watch + sb + doing 强调动作正在进行;+ sb + done 表被动","mark":"see her playing(主动) / see her son awarded(被动)"},{"rule":"现在分词作状语 ≠ 不定式;不定式 to do 多表''将要/目的'',分词表同时/在先","mark":"Hearing …(已听到) ≠ To hear …(为了听)"}],"why":["现在分词带有主动、进行的意味,逻辑主语与主句一致时,用它能把两个动作自然地连在一句话里;一旦主语变成动作的承受者,就要换成表被动的过去分词 done。"],"gaokaoPoints":["V-ing 作状语 vs 过去分词 done 的主动/被动判断(看逻辑主语是施动还是受动);语法填空、短文改错高频。","现在分词与不定式、并列谓语动词的区分:Doing …, he … / He did A, doing B(伴随)。","感官动词 + sb + doing / done 的宾补形式,是写作和单选的常考点。"],"examVsReal":[{"exam":"Hearing the news, he rushed out.（考试/书面）","real":"When he heard the news, he rushed out.","note":"考试爱考分词;口语里用 when/because 引导的状语从句更直白"},{"exam":"The flood hit the town, leaving thousands homeless.（考试）","real":"The flood hit the town, and it left thousands homeless.","note":"考试用分词表结果;口语常用 and 把两句并列"}]}'::jsonb);
